21	// ImageRef names an image for skopeo: Transport is "oci", "dir" or "docker".
22	// For docker, Location is "<host[:port]>/<name>[:tag]" without the "//".
23	type ImageRef struct{ Transport, Location string }
24	
25	// CopyOptions are the options of one copy.
26	type CopyOptions struct {
27		SrcCreds, DestCreds *Credentials // nil = --*-no-creds
28		PreserveDigests     bool
29	}
30	
31	// Credentials is a user and a password for one registry. It prints as
32	// "[REDACTED]" under every fmt verb and in every slog handler, so neither a log
33	// line nor an error built with %v can carry the password.
34	type Credentials struct {
35		User     string
36		Password string `json:"-"`
37	}
38	
39	const redactedCredentials = "Credentials{User: <redacted>, Password: REDACTED"
40	
41	// String implements fmt.Stringer.
42	func (Credentials) String() string { return redactedCredentials }
43	
44	// GoString implements fmt.GoStringer.
45	func (Credentials) GoString() string { return redactedCredentials }
46	
47	// Format implements fmt.Formatter, so no verb (not even %d or %x, which a
48	// Stringer does not cover) can print the fields.
49	func (Credentials) Format(f fmt.State, _ rune) { _, _ = f.Write([]byte(redactedCredentials)) }
50	
51	// LogValue implements slog.LogValuer.
52	func (Credentials) LogValue() slog.Value { return slog.StringValue("[REDACTED]") }
53	
54	// ImageCopier copies images between registries and layouts.
55	type ImageCopier interface {
56		Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error
57		ManifestDigest(ctx context.Context, ref ImageRef, creds *Credentials) (string, error)
58	}
59	
60	const (
61		// skopeoStderrMax is how much of the stderr of skopeo is kept for the
62		// classifier; the text never reaches a message.
63		skopeoStderrMax = 64 << 10
64		// manifestMax is the largest manifest ManifestDigest reads (the limit
65		// registries apply themselves is 4 MiB).
66		manifestMax = 4 << 20
67		// skopeoKillDelay bounds the wait for skopeo's output pipes once it is
68		// killed, in case a child it started still holds them.
69		skopeoKillDelay = 2 * time.Second
70	
71		// policyAcceptAnything is the policy file of every call: skopeo refuses to
72		// run without a readable policy on a host that has none, and the bench has
73		// no signature to check. The default rule is the whole policy.
74		policyAcceptAnything = `{"default":[{"type":"insecureAcceptAnything"}]}`
75	)
76	
77	// skopeoCopier runs the skopeo found on PATH. It is, with kubectl.go and
78	// secrets.go, one of the three files of the package that start a process.
79	type skopeoCopier struct{ path string }
80	
81	// NewSkopeoCopier finds skopeo on PATH. It fails with a SkopeoMissing BenchError
82	// when skopeo is not installed.
83	func NewSkopeoCopier() (ImageCopier, error) {
84		path, err := exec.LookPath("skopeo")
85		if err != nil {
86			return nil, &BenchError{
87				Kind:  SkopeoMissing,
88				Cause: "skopeo was not found on PATH",
89				Check: "install skopeo with your package manager, then run `skopeo --version`",
90				Err:   err,
91			}
92		}
93		return &skopeoCopier{path: path}, nil
94	}
95	
96	// Copy implements ImageCopier: `skopeo copy` of src to dst. A docker reference
97	// whose host is not the loopback is refused before any process starts.
98	func (c *skopeoCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
99		if err := checkSide(src, o.SrcCreds); err != nil {
100			return err
101		}
102		if err := checkSide(dst, o.DestCreds); err != nil {
103			return err
104		}
105		w, err := newSkopeoWorkdir()
106		if err != nil {
107			return err
108		}
109		defer w.remove()
110	
111		args := []string{"--policy", w.policy, "copy"}
112		if o.PreserveDigests {
113			args = append(args, "--preserve-digests")
114		}
115		for _, side := range []struct {
116			flagPrefix string
117			ref        ImageRef
118			creds      *Credentials
119		}{{"--src-", src, o.SrcCreds}, {"--dest-", dst, o.DestCreds}} {
120			flags, err := w.sideFlags(side.flagPrefix, side.ref, side.creds)
121			if err != nil {
122				return err
123			}
124			args = append(args, flags...)
125		}
126		args = append(args, imageArg(src), imageArg(dst))
127	
128		if _, err := c.run(ctx, w, "copy", args, 0); err != nil {
129			return err
130		}
131		return nil
132	}
133	
134	// ManifestDigest implements ImageCopier: the sha256 of the raw manifest of ref,
135	// computed here from `skopeo inspect --raw`, not read from anything skopeo says
136	// about it.
137	func (c *skopeoCopier) ManifestDigest(ctx context.Context, r ImageRef, creds *Credentials) (string, error) {
138		if err := checkSide(r, creds); err != nil {
139			return "", err
140		}
141		w, err := newSkopeoWorkdir()
142		if err != nil {
143			return "", err
144		}
145		defer w.remove()
146	
147		flags, err := w.sideFlags("--", r, creds)
148		if err != nil {
149			return "", err
150		}
151		args := append([]string{"--policy", w.policy, "inspect", "--raw"}, flags...)
152		args = append(args, imageArg(r))
153	
154		manifest, err := c.run(ctx, w, "inspect", args, manifestMax)
155		if err != nil {
156			return "", err
157		}
158		if len(manifest) == 0 {
159			return "", &BenchError{
160				Kind:  SeedFailed,
161				Cause: "skopeo printed no manifest",
162				Check: "run `skopeo inspect --raw` on the same reference by hand",
163			}
164		}
165		sum := sha256.Sum256(manifest)
166		return "sha256:" + hex.EncodeToString(sum[:]), nil
167	}
168	
169	// run starts skopeo with args in the environment of w and returns its stdout
170	// (at most stdoutMax bytes; with 0 the stdout is dropped). Nothing skopeo prints
171	// reaches the error: the stderr only picks its kind.
172	func (c *skopeoCopier) run(ctx context.Context, w *skopeoWorkdir, op string, args []string, stdoutMax int) ([]byte, error) {
173		cmd := exec.CommandContext(ctx, c.path, args...) //nolint:gosec // the binary is the skopeo found on PATH and the references were checked by checkSide
174		cmd.Env = skopeoEnvironment(w.registriesConf)
175		cmd.WaitDelay = skopeoKillDelay
176		stdout, stderr := newCapWriter(stdoutMax), newCapWriter(skopeoStderrMax)
177		cmd.Stdout, cmd.Stderr = stdout, stderr
178	
179		runErr := cmd.Run()
180		if runErr == nil {
181			if stdoutMax > 0 && stdout.over {
182				return nil, &BenchError{
183					Kind:  SeedFailed,
184					Cause: "the manifest is larger than the 4 MiB registries accept",
185					Check: "run `skopeo inspect --raw` on the same reference by hand",
186				}
187			}
188			return stdout.buf.Bytes(), nil
189		}
190		if ctxErr := ctx.Err(); ctxErr != nil {
191			kind := Unclassified
192			if errors.Is(ctxErr, context.DeadlineExceeded) {
193				kind = Deadline
194			}
195			return nil, &BenchError{
196				Kind:  kind,
197				Cause: fmt.Sprintf("skopeo %s was interrupted", op),
198				Check: "run the command again",
199				Err:   ctxErr,
200			}
201		}
202		return nil, skopeoFailure(op, classifySkopeo(stderr.buf.String()), runErr)
203	}
204	
205	// skopeoFailure builds the error of a skopeo that exited with a failure.
206	func skopeoFailure(op string, kind ErrKind, runErr error) *BenchError {
207		be := &BenchError{Kind: kind, Err: runErr}
208		switch kind {
209		case RegistryUnreachable:
210			be.Cause = fmt.Sprintf("skopeo %s could not reach a registry", op)
211			be.Check = "check that the port-forward is running and the registry answers on its port"
212		case RegistryRefused:
213			be.Cause = fmt.Sprintf("a registry refused the skopeo %s", op)
214			be.Check = "check the bench credentials in the secrets file and the privileges of the account"
215		case SeedFailed:
216			be.Cause = fmt.Sprintf("skopeo %s did not find the image", op)
217			be.Check = "check that the image and its tag exist in the source registry"
218		default:
219			be.Cause = fmt.Sprintf("skopeo %s failed", op)
220			be.Check = "run the same skopeo command by hand to see what it says"
221		}
222		return be
223	}
224	
225	// imageArg is how skopeo is given an ImageRef: docker://<location>, or
226	// <transport>:<location>.
227	func imageArg(r ImageRef) string {
228		if r.Transport == "docker" {
229			return "docker://" + r.Location
230		}
231		return r.Transport + ":" + r.Location
232	}
233	
234	// checkSide refuses, before any process starts, a reference skopeo must not be
235	// given: an unknown transport, credentials for a side that is not a registry,
236	// and a docker reference whose host is not the loopback (TLS verification is
237	// switched off for every docker reference, so the host is the only protection).
238	func checkSide(r ImageRef, creds *Credentials) error {
239		switch r.Transport {
240		case "oci", "dir":
241			if creds != nil {
242				return &BenchError{
243					Kind:  Unclassified,
244					Cause: "credentials were given for an image that is not in a registry",
245					Check: "give credentials only for a docker reference",
246				}
247			}
248			return nil
249		case "docker":
250			if !loopbackRegistry(registryHost(r.Location)) {
251				return &BenchError{
252					Kind:  Unclassified,
253					Cause: "the bench only talks to a registry on the loopback: TLS verification is off for it",
254					Check: "reach the registry through the port-forward (127.0.0.1) and give that address",
255				}
256			}
257			return nil
258		}
259		return &BenchError{
260			Kind:  Unclassified,
261			Cause: "the image transport is not one of oci, dir and docker",
262			Check: "give a reference whose transport is oci, dir or docker",
263		}
264	}
265	
266	// registryHost is the "<host[:port]>" part of a docker location.
267	func registryHost(location string) string {
268		host, _, _ := strings.Cut(location, "/")
269		return host
270	}
271	
272	// loopbackRegistry tells whether hostPort ("127.0.0.1:5000", "localhost",
273	// "[::1]:5000") names the loopback and nothing else. It parses the host and the
274	// port instead of testing a prefix, so "127.0.0.1@evil.com",
275	// "127.0.0.1.evil.com" and "127.0.0.1:5000@evil.com" are not the loopback.
276	func loopbackRegistry(hostPort string) bool {
277		host := hostPort
278		if h, p, err := net.SplitHostPort(hostPort); err == nil {
279			if n, err := strconv.Atoi(p); err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != p {
280				return false
281			}
282			host = h
283			if strings.HasPrefix(hostPort, "[") {
284				return host == "::1"
285			}
286		} else if strings.HasPrefix(hostPort, "[") && strings.HasSuffix(hostPort, "]") {
287			return hostPort == "[::1]"
288		}
289		return host == "127.0.0.1" || host == "localhost"
290	}
291	
292	// skopeoWorkdir is the temporary folder of one skopeo call: the policy, the
293	// empty registries.conf and the authentication files. The folder is 0700, the
294	// files are 0600, and remove deletes all of it whatever happened.
295	type skopeoWorkdir struct {
296		dir            string
297		policy         string
298		registriesConf string
299	}
300	
301	// newSkopeoWorkdir creates the folder with the policy and the empty
302	// registries.conf already in it.
303	func newSkopeoWorkdir() (*skopeoWorkdir, error) {
304		dir, err := os.MkdirTemp("", "devdesk-skopeo-") // 0700
305		if err != nil {
306			return nil, &BenchError{
307				Kind:  Unclassified,
308				Cause: "the temporary folder for skopeo could not be created",
309				Check: "check that the temporary folder is writable and not full",
310				Err:   err,
311			}
312		}
313		w := &skopeoWorkdir{dir: dir, policy: filepath.Join(dir, "policy.json"), registriesConf: filepath.Join(dir, "registries.conf")}
314		for path, content := range map[string]string{w.policy: policyAcceptAnything, w.registriesConf: ""} {
315			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
316				w.remove()
317				return nil, workdirError(err)
318			}
319		}
320		return w, nil
321	}
322	
323	// remove deletes the folder and everything in it. It is called by defer, so it
324	// runs after a failure and a cancellation as well.
325	func (w *skopeoWorkdir) remove() { _ = os.RemoveAll(w.dir) }
326	
327	func workdirError(err error) *BenchError {
328		return &BenchError{
329			Kind:  Unclassified,
330			Cause: "a temporary file for skopeo could not be written",
331			Check: "check that the temporary folder is writable and not full",
332			Err:   err,
333		}
334	}
335	
336	// sideFlags returns the flags of one side of a call, for a flag prefix of
337	// "--src-", "--dest-" or "--": TLS verification off for a docker reference only,
338	// and either "<prefix>no-creds" or "<prefix>authfile <file>" holding the
339	// credentials. The credentials go to a file because an argument is visible to
340	// every account through /proc.
341	func (w *skopeoWorkdir) sideFlags(prefix string, r ImageRef, creds *Credentials) ([]string, error) {
342		var flags []string
343		if r.Transport == "docker" {
344			flags = append(flags, prefix+"tls-verify=false")
345		}
346		if creds == nil {
347			return append(flags, prefix+"no-creds"), nil
348		}
349		// One file per side, so the credentials of a side are never offered to the other.
350		name := "auth.json"
351		if prefix != "--" {
352			name = strings.Trim(prefix, "-") + "-auth.json"
353		}
354		path := filepath.Join(w.dir, name)
355		content, err := json.Marshal(map[string]any{"auths": map[string]any{
356			registryHost(r.Location): map[string]string{"auth": base64.StdEncoding.EncodeToString([]byte(creds.User + ":" + creds.Password))},
357		}})
358		if err != nil {
359			return nil, workdirError(err)
360		}
361		if err := os.WriteFile(path, content, 0o600); err != nil {
362			return nil, workdirError(err)
363		}
364		return append(flags, prefix+"authfile", path), nil
365	}
366	
367	// skopeoEnvironment is the environment of the skopeo process: the caller's,
368	// without the proxy variables (which would send the bench traffic elsewhere),
369	// REGISTRY_AUTH_FILE (which would name a login of the host) and every
370	// CONTAINERS_* variable (which would change the configuration, the policy or the
371	// certificates), and with CONTAINERS_REGISTRIES_CONF pointing at registriesConf,
372	// an empty file, so no mirror or redirect of the host applies. Names are compared
373	// in upper case because Windows environment names are case-insensitive.
374	func skopeoEnvironment(registriesConf string) []string {
375		var env []string
376		for _, kv := range os.Environ() {
377			name, _, _ := strings.Cut(kv, "=")
378			upper := strings.ToUpper(name)
379			switch upper {
380			case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
381				continue
382			}
383			if strings.HasPrefix(upper, "CONTAINERS_") {
384				continue
385			}
386			env = append(env, kv)
387		}
388		return append(env, "CONTAINERS_REGISTRIES_CONF="+registriesConf)
389	}
