14		"time"
15	)
16	
17	// Runner runs one kubectl command. args are the arguments after "kubectl" and
18	// carry no --context: the runner adds it. stdin is sent to the command when it
19	// is not empty. Both streams are returned even on failure, because the stderr
20	// of a failed call is what classifyKubectl reads.
21	type Runner interface {
22		Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error)
23	}
24	
25	// execRunner runs the kubectl found on PATH against one context.
26	type execRunner struct {
27		path    string
28		context string
29	}
30	
31	// NewExecRunner finds kubectl on PATH and returns a Runner that passes
32	// "--context <kubeContext>" to every call. It fails with a KubectlMissing
33	// BenchError when kubectl is not installed. This is the one place of the
34	// package that starts a process.
35	func NewExecRunner(kubeContext string) (Runner, error) {
36		path, err := lookKubectl()
37		if err != nil {
38			return nil, err
39		}
40		return &execRunner{path: path, context: kubeContext}, nil
41	}
42	
43	// lookKubectl finds kubectl on PATH, or returns a KubectlMissing BenchError.
44	func lookKubectl() (string, error) {
45		path, err := exec.LookPath("kubectl")
46		if err != nil {
47			return "", &BenchError{
48				Kind:  KubectlMissing,
49				Cause: "kubectl was not found on PATH",
50				Check: "run `mise install` to get kubectl, then `kubectl version --client`",
51				Err:   err,
52			}
53		}
54		return path, nil
55	}
56	
57	// Run implements Runner.
58	func (r *execRunner) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
59		full := append([]string{"--context", r.context}, args...)
60		cmd := exec.CommandContext(ctx, r.path, full...) //nolint:gosec // the binary is the kubectl found on PATH and the arguments are built by this package from validated parameters
61		if len(stdin) > 0 {
62			cmd.Stdin = bytes.NewReader(stdin)
63		}
64		var out, errOut bytes.Buffer
65		cmd.Stdout, cmd.Stderr = &out, &errOut
66		err = cmd.Run()
67		return out.Bytes(), errOut.Bytes(), err
68	}
69	
70	// portForwardTimeout is how long Forward waits for kubectl to print the line
71	// that names the local port. A variable so a test can shorten it.
72	var portForwardTimeout = 15 * time.Second
73	
74	const (
75		// forwardKillDelay bounds the wait for kubectl's output pipes once it is
76		// killed, in case a child it started still holds them.
77		forwardKillDelay = 2 * time.Second
78		// forwardStderrMax is how much of the stderr of kubectl port-forward is kept
79		// for the classifier.
80		forwardStderrMax = 16 << 10
81		// forwardLineMax bounds a line kubectl prints without a line end.
82		forwardLineMax = 4 << 10
83		// forwardLoopback is the only address Forward binds and accepts.
84		forwardLoopback = "127.0.0.1"
85	)
86	
87	// resourceName is what a namespace or a Service name must look like before it
88	// reaches an argument of kubectl.
89	var resourceName = regexp.MustCompile(`^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$`)
90	
91	// PortForwarder forwards a local loopback port to a port of a Service.
92	type PortForwarder interface {
93		Forward(ctx context.Context, namespace, service string, port int) (local string, stop func() error, err error)
94	}
95	
96	// execPortForwarder runs `kubectl port-forward` from the kubectl on PATH.
97	type execPortForwarder struct {
98		path    string
99		context string
100	}
101	
102	// NewExecPortForwarder finds kubectl on PATH and returns a PortForwarder that
103	// passes "--context <kubeContext>" to every call. It fails with a KubectlMissing
104	// BenchError when kubectl is not installed. With NewExecRunner, it is one of the
105	// two doors of the package to kubectl.
106	func NewExecPortForwarder(kubeContext string) (PortForwarder, error) {
107		path, err := lookKubectl()
108		if err != nil {
109			return nil, err
110		}
111		return &execPortForwarder{path: path, context: kubeContext}, nil
112	}
113	
114	// Forward starts `kubectl port-forward svc/<service> :<port> --address
115	// 127.0.0.1` and returns the local "127.0.0.1:<port>" kubectl chose. The
116	// forward ends when stop is called or ctx is done; stop kills kubectl and waits
117	// for it, and may be called any number of times. On an error no process is left
118	// running.
119	func (f *execPortForwarder) Forward(ctx context.Context, namespace, service string, port int) (string, func() error, error) {
120		if !resourceName.MatchString(namespace) || !resourceName.MatchString(service) || port < 1 || port > 65535 {
121			return "", nil, &BenchError{
122				Kind:  Unclassified,
123				Cause: "the port-forward target is not valid",
124				Check: "give a namespace and a Service name made of lower case letters, digits, '-' and '.', and a port from 1 to 65535",
125			}
126		}
127		if err := ctx.Err(); err != nil {
128			return "", nil, forwardInterrupted(err)
129		}
130	
131		lines := &forwardLineWriter{found: make(chan string, 1)}
132		stderr := newCapWriter(forwardStderrMax)
133		args := []string{"--context", f.context, "-n", namespace, "port-forward", "svc/" + service, ":" + strconv.Itoa(port), "--address", forwardLoopback}
134		cmd := exec.CommandContext(ctx, f.path, args...) //nolint:gosec // the binary is the kubectl found on PATH and the arguments are validated above
135		cmd.Stdout, cmd.Stderr = lines, stderr
136		cmd.WaitDelay = forwardKillDelay
137		if err := cmd.Start(); err != nil {
138			return "", nil, &BenchError{
139				Kind:  Unclassified,
140				Cause: "kubectl port-forward could not be started",
141				Check: "run `kubectl version --client` to see whether kubectl runs",
142				Err:   err,
143			}
144		}
145		pf := &portForward{cmd: cmd, done: make(chan struct{})}
146		// The one goroutine that waits: it reaps kubectl whoever ends it (stop, the
147		// context, kubectl itself) and publishes the end through done.
148		go func() {
149			pf.waitErr = cmd.Wait()
150			close(pf.done)
151		}()
152	
153		timer := time.NewTimer(portForwardTimeout)
154		defer timer.Stop()
155		select {
156		case local := <-lines.found:
157			return local, pf.stop, nil
158		case <-pf.done:
159			// The copy of the output ends before Wait returns, so a line printed
160			// just before the exit is already in found.
161			select {
162			case local := <-lines.found:
163				return local, pf.stop, nil
164			default:
165			}
166			return "", nil, forwardExited(namespace, service, stderr.buf.String(), pf.waitErr)
167		case <-timer.C:
168			_ = pf.stop()
169			return "", nil, &BenchError{
170				Kind:  Deadline,
171				Cause: fmt.Sprintf("kubectl did not report a local port within %s", portForwardTimeout),
172				Check: fmt.Sprintf("run `kubectl --context %s -n %s port-forward svc/%s :%d` by hand and see whether the Service has a ready pod", f.context, namespace, service, port),
173			}
174		case <-ctx.Done():
175			_ = pf.stop()
176			return "", nil, forwardInterrupted(ctx.Err())
177		}
178	}
179	
180	// forwardInterrupted is the error of a forward the context ended.
181	func forwardInterrupted(err error) error {
182		kind := Unclassified
183		if errors.Is(err, context.DeadlineExceeded) {
184			kind = Deadline
185		}
186		return &BenchError{
187			Kind:  kind,
188			Cause: "the port-forward was interrupted before it was ready",
189			Check: "run the command again",
190			Err:   err,
191		}
192	}
193	
194	// forwardExited is the error of a kubectl that ended before naming a port. The
195	// stderr only picks the kind: it never reaches the message, because it can carry
196	// a token or a server address.
197	func forwardExited(namespace, service, stderr string, runErr error) error {
198		return &BenchError{
199			Kind:  classifyKubectl(stderr),
200			Cause: "kubectl port-forward ended before it reported a local port",
201			Check: fmt.Sprintf("run `kubectl -n %s port-forward svc/%s` by hand to see why", namespace, service),
202			Err:   runErr,
203		}
204	}
205	
206	// portForward is one running `kubectl port-forward`.
207	type portForward struct {
208		cmd     *exec.Cmd
209		done    chan struct{} // closed once cmd.Wait has returned
210		waitErr error         // set before done is closed
211		once    sync.Once
212	}
213	
214	// stop kills kubectl and waits until it is gone. It is idempotent and always
215	// returns nil: a process that already ended is the goal, not a failure.
216	func (p *portForward) stop() error {
217		p.once.Do(func() { _ = p.cmd.Process.Kill() })
218		<-p.done
219		return nil
220	}
221	
222	// forwardLineWriter reads what kubectl prints, line by line, and publishes the
223	// first address parseForwardingLine accepts; after that it drops the output
224	// ("Handling connection for ..." goes on for as long as the forward lives).
225	type forwardLineWriter struct {
226		found   chan string // capacity 1
227		pending []byte
228		done    bool
229	}
230	
231	// Write implements io.Writer. os/exec calls it from one goroutine.
232	func (w *forwardLineWriter) Write(p []byte) (int, error) {
233		n := len(p)
234		if w.done {
235			return n, nil
236		}
237		w.pending = append(w.pending, p...)
238		for {
239			end := bytes.IndexByte(w.pending, '\n')
240			if end < 0 {
241				break
242			}
243			line := string(w.pending[:end])
244			w.pending = w.pending[end+1:]
245			if local, ok := parseForwardingLine(line); ok {
246				w.found <- local
247				w.done, w.pending = true, nil
248				return n, nil
249			}
250		}
251		if len(w.pending) > forwardLineMax {
252			w.pending = nil
253		}
254		return n, nil
255	}
256	
257	// parseForwardingLine reads the line kubectl prints once a port is bound,
258	// "Forwarding from 127.0.0.1:41234 -> 5000". Only an IPv4 loopback address with
259	// a port from 1 to 65535 is accepted; an IPv6 line (kubectl prints both for
260	// "localhost") and anything else is ignored.
261	func parseForwardingLine(line string) (hostPort string, ok bool) {
262		rest, found := strings.CutPrefix(strings.TrimSpace(line), "Forwarding from ")
263		if !found {
264			return "", false
265		}
266		addr, _, found := strings.Cut(rest, " -> ")
267		if !found {
268			return "", false
269		}
270		host, portText, err := net.SplitHostPort(addr)
271		if err != nil || host != forwardLoopback {
272			return "", false
273		}
274		port, err := strconv.Atoi(portText)
275		if err != nil || port < 1 || port > 65535 || strconv.Itoa(port) != strings.TrimLeft(portText, "0") {
276			return "", false
277		}
278		return net.JoinHostPort(forwardLoopback, strconv.Itoa(port)), true
279	}
