134	// ManifestDigest implements ImageCopier: the sha256 of the raw manifest of ref,
135	// computed here from `skopeo inspect --raw`, not read from anything skopeo says
136	// about it.
137	func (c *skopeoCopier) ManifestDigest(ctx context.Context, r ImageRef, creds *Credentials) (string, error) {
138		if err := checkSide(r, creds); err != nil {
139			return "", err
140		}
141		w, err := newSkopeoWorkdir()
142		if err != nil {
143			return "", err
144		}
145		defer w.remove()
146	
147		flags, err := w.sideFlags("--", r, creds)
148		if err != nil {
149			return "", err
150		}
151		args := append([]string{"--policy", w.policy, "inspect", "--raw"}, flags...)
152		args = append(args, imageArg(r))
153	
154		manifest, err := c.run(ctx, w, "inspect", args, manifestMax)
155		if err != nil {
156			return "", err
157		}
158		if len(manifest) == 0 {
159			return "", &BenchError{
160				Kind:  SeedFailed,
161				Cause: "skopeo printed no manifest",
162				Check: "run `skopeo inspect --raw` on the same reference by hand",
163			}
