189		}
190		if ctxErr := ctx.Err(); ctxErr != nil {
191			kind := Unclassified
192			if errors.Is(ctxErr, context.DeadlineExceeded) {
193				kind = Deadline
194			}
195			return nil, &BenchError{
196				Kind:  kind,
197				Cause: fmt.Sprintf("skopeo %s was interrupted", op),
198				Check: "run the command again",
199				Err:   ctxErr,
200			}
201		}
202		return nil, skopeoFailure(op, classifySkopeo(stderr.buf.String()), runErr)
203	}
