225	// imageArg is how skopeo is given an ImageRef: docker://<location>, or
226	// <transport>:<location>.
227	func imageArg(r ImageRef) string {
228		if r.Transport == "docker" {
229			return "docker://" + r.Location
230		}
231		return r.Transport + ":" + r.Location
