234	// checkSide refuses, before any process starts, a reference skopeo must not be
235	// given: an unknown transport, credentials for a side that is not a registry,
236	// and a docker reference whose host is not the loopback (TLS verification is
237	// switched off for every docker reference, so the host is the only protection).
238	func checkSide(r ImageRef, creds *Credentials) error {
239		switch r.Transport {
240		case "oci", "dir":
241			if creds != nil {
242				return &BenchError{
243					Kind:  Unclassified,
244					Cause: "credentials were given for an image that is not in a registry",
245					Check: "give credentials only for a docker reference",
246				}
247			}
248			return nil
249		case "docker":
250			if !loopbackRegistry(registryHost(r.Location)) {
251				return &BenchError{
252					Kind:  Unclassified,
253					Cause: "the bench only talks to a registry on the loopback: TLS verification is off for it",
254					Check: "reach the registry through the port-forward (127.0.0.1) and give that address",
255				}
256			}
257			return nil
258		}
259		return &BenchError{
260			Kind:  Unclassified,
261			Cause: "the image transport is not one of oci, dir and docker",
262			Check: "give a reference whose transport is oci, dir or docker",
263		}
264	}
