266	// registryHost is the "<host[:port]>" part of a docker location.
267	func registryHost(location string) string {
268		host, _, _ := strings.Cut(location, "/")
269		return host
270	}
271	
272	// loopbackRegistry tells whether hostPort ("127.0.0.1:5000", "localhost",
273	// "[::1]:5000") names the loopback and nothing else. It parses the host and the
274	// port instead of testing a prefix, so "127.0.0.1@evil.com",
275	// "127.0.0.1.evil.com" and "127.0.0.1:5000@evil.com" are not the loopback.
276	func loopbackRegistry(hostPort string) bool {
277		host := hostPort
278		if h, p, err := net.SplitHostPort(hostPort); err == nil {
279			if n, err := strconv.Atoi(p); err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != p {
280				return false
281			}
282			host = h
283			if strings.HasPrefix(hostPort, "[") {
284				return host == "::1"
285			}
286		} else if strings.HasPrefix(hostPort, "[") && strings.HasSuffix(hostPort, "]") {
287			return hostPort == "[::1]"
288		}
289		return host == "127.0.0.1" || host == "localhost"
290	}
