292	// skopeoWorkdir is the temporary folder of one skopeo call: the policy, the
293	// empty registries.conf and the authentication files. The folder is 0700, the
294	// files are 0600, and remove deletes all of it whatever happened.
295	type skopeoWorkdir struct {
296		dir            string
297		policy         string
298		registriesConf string
299	}
300	
301	// newSkopeoWorkdir creates the folder with the policy and the empty
302	// registries.conf already in it.
303	func newSkopeoWorkdir() (*skopeoWorkdir, error) {
304		dir, err := os.MkdirTemp("", "devdesk-skopeo-") // 0700
305		if err != nil {
306			return nil, &BenchError{
307				Kind:  Unclassified,
308				Cause: "the temporary folder for skopeo could not be created",
309				Check: "check that the temporary folder is writable and not full",
310				Err:   err,
311			}
312		}
313		w := &skopeoWorkdir{dir: dir, policy: filepath.Join(dir, "policy.json"), registriesConf: filepath.Join(dir, "registries.conf")}
314		for path, content := range map[string]string{w.policy: policyAcceptAnything, w.registriesConf: ""} {
315			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
316				w.remove()
317				return nil, workdirError(err)
318			}
319		}
320		return w, nil
321	}
322	
323	// remove deletes the folder and everything in it. It is called by defer, so it
324	// runs after a failure and a cancellation as well.
325	func (w *skopeoWorkdir) remove() { _ = os.RemoveAll(w.dir) }
326	
327	func workdirError(err error) *BenchError {
328		return &BenchError{
329			Kind:  Unclassified,
330			Cause: "a temporary file for skopeo could not be written",
331			Check: "check that the temporary folder is writable and not full",
332			Err:   err,
333		}
334	}
335	
336	// sideFlags returns the flags of one side of a call, for a flag prefix of
337	// "--src-", "--dest-" or "--": TLS verification off for a docker reference only,
338	// and either "<prefix>no-creds" or "<prefix>authfile <file>" holding the
339	// credentials. The credentials go to a file because an argument is visible to
340	// every account through /proc.
341	func (w *skopeoWorkdir) sideFlags(prefix string, r ImageRef, creds *Credentials) ([]string, error) {
342		var flags []string
343		if r.Transport == "docker" {
344			flags = append(flags, prefix+"tls-verify=false")
345		}
346		if creds == nil {
347			return append(flags, prefix+"no-creds"), nil
348		}
349		// One file per side, so the credentials of a side are never offered to the other.
350		name := "auth.json"
351		if prefix != "--" {
352			name = strings.Trim(prefix, "-") + "-auth.json"
353		}
354		path := filepath.Join(w.dir, name)
355		content, err := json.Marshal(map[string]any{"auths": map[string]any{
356			registryHost(r.Location): map[string]string{"auth": base64.StdEncoding.EncodeToString([]byte(creds.User + ":" + creds.Password))},
357		}})
358		if err != nil {
359			return nil, workdirError(err)
360		}
361		if err := os.WriteFile(path, content, 0o600); err != nil {
362			return nil, workdirError(err)
363		}
364		return append(flags, prefix+"authfile", path), nil
365	}
366	
367	// skopeoEnvironment is the environment of the skopeo process: the caller's,
368	// without the proxy variables (which would send the bench traffic elsewhere),
369	// REGISTRY_AUTH_FILE (which would name a login of the host) and every
370	// CONTAINERS_* variable (which would change the configuration, the policy or the
371	// certificates), and with CONTAINERS_REGISTRIES_CONF pointing at registriesConf,
372	// an empty file, so no mirror or redirect of the host applies. Names are compared
373	// in upper case because Windows environment names are case-insensitive.
374	func skopeoEnvironment(registriesConf string) []string {
375		var env []string
376		for _, kv := range os.Environ() {
377			name, _, _ := strings.Cut(kv, "=")
378			upper := strings.ToUpper(name)
379			switch upper {
380			case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
381				continue
382			}
383			if strings.HasPrefix(upper, "CONTAINERS_") {
384				continue
385			}
386			env = append(env, kv)
387		}
388		return append(env, "CONTAINERS_REGISTRIES_CONF="+registriesConf)
389	}
